import math

def Cout(my_list):
	freq = {}
	for item in my_list:
		if item in freq:
			freq[item] += 1
		else:
			freq[item] = 1
	return freq

def sr(n, m):
	(s, p) = (0, 1)
	if n >= m:
		n = m - 1
	for i in range(1, n + 1):
		p *= i
		p %= m
		s += i * p % m
		s %= m
	return s % m

def ss(n, m):
	m *= 2
	p = n ** 2 % m
	p *= (n + 1) % m
	return p // 2
(n, m) = map(int, input().split())
a = list(map(int, input().split()))
(b, t, s, p, cf) = (Cout(a), 0, 0, 1, [])
for i in range(1, m):
	p *= i + 1
	p = p % m
	s = p - 1 + m
	cf.append(s % m)
for i in b:
	if i >= m:
		r = len(cf) - 1
	else:
